PRAGMA foreign_keys=ON;
CREATE TABLE locations(id TEXT PRIMARY KEY,ubigeo TEXT UNIQUE,department TEXT,province TEXT,district TEXT,latitude REAL,longitude REAL,verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE institutions(id TEXT PRIMARY KEY,source_identifier TEXT NOT NULL,official_name TEXT NOT NULL,location_id TEXT REFERENCES locations(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(source_identifier));
CREATE TABLE suppliers(id TEXT PRIMARY KEY,ruc TEXT,official_name TEXT NOT NULL,location_id TEXT REFERENCES locations(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(ruc));
CREATE TABLE datasets(id TEXT PRIMARY KEY,name TEXT NOT NULL,source_institution TEXT NOT NULL,source_url TEXT NOT NULL,coverage_start TEXT,coverage_end TEXT,update_frequency TEXT,license_status TEXT,limitations TEXT,created_at TEXT NOT NULL);
CREATE TABLE import_batches(id TEXT PRIMARY KEY,dataset_id TEXT NOT NULL REFERENCES datasets(id),retrieved_at TEXT NOT NULL,published_at TEXT,original_filename TEXT,sha256 TEXT NOT NULL,parser_version TEXT NOT NULL,normalization_version TEXT NOT NULL,status TEXT NOT NULL,record_count INTEGER NOT NULL DEFAULT 0,errors_json TEXT NOT NULL DEFAULT '[]',warnings_json TEXT NOT NULL DEFAULT '[]',UNIQUE(dataset_id,sha256));
CREATE TABLE procurement_records(id TEXT PRIMARY KEY,dataset_id TEXT NOT NULL REFERENCES datasets(id),import_batch_id TEXT NOT NULL REFERENCES import_batches(id),source_identifier TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN('process','award','contract','order','payment')),description TEXT,institution_id TEXT REFERENCES institutions(id),supplier_id TEXT REFERENCES suppliers(id),procedure_type TEXT,status TEXT,currency TEXT,estimated_amount_minor INTEGER,award_amount_minor INTEGER,contract_amount_minor INTEGER,paid_amount_minor INTEGER,publication_date TEXT,award_date TEXT,source_url TEXT,source_payload_hash TEXT NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(dataset_id,source_identifier,stage));
CREATE TABLE procurement_items(id TEXT PRIMARY KEY,procurement_id TEXT NOT NULL REFERENCES procurement_records(id),description TEXT,quantity_text TEXT,unit TEXT,unit_price_minor INTEGER,category_code TEXT);
CREATE TABLE bidders(id TEXT PRIMARY KEY,procurement_id TEXT NOT NULL REFERENCES procurement_records(id),supplier_id TEXT REFERENCES suppliers(id),recorded_name TEXT NOT NULL,bid_amount_minor INTEGER,currency TEXT);
CREATE TABLE source_lineage(id TEXT PRIMARY KEY,procurement_id TEXT NOT NULL REFERENCES procurement_records(id),source_record_id TEXT NOT NULL,row_number INTEGER,raw_object_key TEXT,field_map_json TEXT NOT NULL);
CREATE TABLE indicator_definitions(id TEXT PRIMARY KEY,name TEXT NOT NULL,version TEXT NOT NULL,definition_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(id,version));
CREATE TABLE indicator_executions(id TEXT PRIMARY KEY,indicator_id TEXT NOT NULL,indicator_version TEXT NOT NULL,executed_at TEXT NOT NULL,input_batch_ids_json TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE analytical_findings(id TEXT PRIMARY KEY,execution_id TEXT NOT NULL REFERENCES indicator_executions(id),institution_id TEXT REFERENCES institutions(id),supplier_id TEXT REFERENCES suppliers(id),period_start TEXT,period_end TEXT,value_json TEXT NOT NULL,methodology_snapshot_json TEXT NOT NULL);
CREATE TABLE finding_records(finding_id TEXT NOT NULL REFERENCES analytical_findings(id),procurement_id TEXT NOT NULL REFERENCES procurement_records(id),PRIMARY KEY(finding_id,procurement_id));
CREATE TABLE community_submissions(id TEXT PRIMARY KEY,type TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,source_url TEXT,contact_email TEXT,status TEXT NOT NULL CHECK(status IN('received','under_review','needs_information','accepted','rejected','implemented','closed')),created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE moderation_events(id TEXT PRIMARY KEY,submission_id TEXT NOT NULL REFERENCES community_submissions(id),actor_subject TEXT NOT NULL,from_status TEXT,to_status TEXT NOT NULL,notes TEXT,created_at TEXT NOT NULL);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,actor_subject TEXT,created_at TEXT NOT NULL,metadata_json TEXT NOT NULL);
CREATE VIRTUAL TABLE search_index USING fts5(entity_type,entity_id UNINDEXED,display_name,aliases, tokenize='unicode61 remove_diacritics 2');
CREATE INDEX idx_proc_inst_date ON procurement_records(institution_id,award_date);CREATE INDEX idx_proc_sup_date ON procurement_records(supplier_id,award_date);CREATE INDEX idx_proc_amount ON procurement_records(award_amount_minor);CREATE INDEX idx_submissions_status ON community_submissions(status,created_at);
